#!/usr/bin/env bash
# Regenerate src/t3/*.ts from the captured t3code pages in runs/t3/ (see shots.ts --capture).
set -euo pipefail
cd "$(dirname "$0")/.."
cap=runs/t3
g() { python3 gen/dom2foldkit.py "$@"; }
header() {
	cat <<'H'
// Generated by gen/gen.sh from t3code's rendered DOM: github.com/pingdotgg/t3code, apps/web/src (Sidebar.tsx,
// chat/ChatComposer.tsx, chat/DraftHeroHeadline.tsx and their ui/ components) at fe27e8e3, as served by the
// t3code-nightly-bin build on the Beelink. Spike 2 only: markup and classes copied to judge parity.
//
// MIT License. Copyright (c) 2026 T3 Tools Inc.
// Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated
// documentation files (the "Software"), to deal in the Software without restriction, including without limitation
// the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to
// permit persons to whom the Software is furnished to do so, subject to the following conditions: The above copyright
// notice and this permission notice shall be included in all copies or substantial portions of the Software.
// THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND.
/* eslint-disable */
import type { Html } from "foldkit/html"
import type { HtmlBuilder } from "foldkit/html"
H
}
LIST='role=presentation&&class=relative flex flex-col gap-px flex-1=slots.threadList'
EDITOR='class=relative flow-root font-(family-name:--font-composer,var(--font-sans)) text-(length:--font-size-prompt,var(--text-sm)) max-sm:pointer-coarse:text-(length:--font-size-prompt-touch)=slots.editor'
PROJECT='readonly project: string; readonly monogram: string; readonly tone: string'
SLOTS_T="slots: { readonly threadList: Html; readonly editor: Html; $PROJECT }"
SLOTS_M="slots: { readonly editor: Html; $PROJECT }"
DRAFT=(--text "New thread in cairn='New thread in ' + slots.project" --text "cairn=slots.project" --text "~CN=slots.monogram" --text "text-amber-600 dark:text-amber-400=slots.tone")
{
	header
	# The thread details panel is outside the surfaces S2 judges; the harness closes it in t3code too.
	g $cap/1440.html class=contents --name desktopPage --params "$SLOTS_T" --slot "$LIST" --slot "$EDITOR" --slot "aria-label=Thread details=null" "${DRAFT[@]}"
	g $cap/390.html class=contents --name mobilePage --params "$SLOTS_M" --slot "$EDITOR" "${DRAFT[@]}"
	g $cap/390-sidebar.html class=contents --name mobileSidebarPage --params "$SLOTS_M" --slot "$EDITOR" "${DRAFT[@]}"
	g $cap/390-sidebar.html "role=presentation&&data-slot=sheet-viewport" --name mobileSidebarSheet --params "slots: { readonly threadList: Html }" --slot "$LIST"
} >src/t3/pages.ts
{
	header
	echo 'import type { Row } from "../model"'
	echo
	g $cap/1440.html data-testid=sidebar-row-card --nth 0 --name rowWorking --params "row: Row" \
		--text "Executor MCP Stdio Bridges=row.title" --text "~cairn=row.project" --text "~CN=row.monogram" --text "text-amber-600 dark:text-amber-400=row.tone" --text "~3m=row.age" --text "~2m=row.age" --text "~main=row.branch ?? ''"
	g $cap/1440.html data-testid=sidebar-row-card --nth 1 --name rowIdle --params "row: Row" \
		--text "Codebase status overview=row.title" --text "~supervillain=row.project" --text "~SN=row.monogram" --text "text-orange-600 dark:text-orange-400=row.tone" --text "~3m=row.age" --text "~2m=row.age"
	g $cap/1440.html data-testid=sidebar-settled-header --name settledHeader --params "count: number" --text "~145=String(count)"
} >src/t3/rows.ts
# Cairn's page has no thread details panel, so the chat lane keeps no room for one.
sed -i 's/"--chat-lane-inset-end": "200px"/"--chat-lane-inset-end": "0px"/g' src/t3/pages.ts
wc -c src/t3/*.ts
